    #(
        .sel(sel)
    )
`endif // ifdef DEFINE_SF_RTL_MODULE_PARAMETERS
    x_sm_hssi_pcie_pcs_rst_mux (
        .i_hps_rst_rstn(i_hps_rst_rstn),
        .i_same_quad_pcs_rst_rstn(i_same_quad_pcs_rst_rstn),
        .i_unused_rstn(i_unused_rstn),
